export const ADMIN_HTML = "<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"/>\n<meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\"/>\n<meta http-equiv=\"Pragma\" content=\"no-cache\"/>\n<meta http-equiv=\"Expires\" content=\"0\"/>\n<!-- v20260418 -->\n<title>Admin Console – StudySignal</title>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js\"></script>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\n:root{\n  --bg:#0f172a;--sidebar:#1e293b;--border:#334155;\n  --text:#f1f5f9;--muted:#94a3b8;--primary:#6366f1;\n  --success:#10b981;--warn:#f59e0b;--danger:#ef4444;\n  --card:#1e293b;--card2:#263348;\n}\nbody{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;display:flex}\na{color:inherit;text-decoration:none}\nbutton{cursor:pointer;font-family:inherit}\ninput,select{font-family:inherit}\n\n/* ── Layout ── */\n#sidebar{width:220px;min-height:100vh;background:var(--sidebar);border-right:1px solid var(--border);display:flex;flex-direction:column;flex-shrink:0;position:fixed;top:0;left:0;bottom:0;z-index:50}\n#main{margin-left:220px;flex:1;min-height:100vh;display:flex;flex-direction:column}\n#topbar{height:52px;background:rgba(30,41,59,0.95);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:40;backdrop-filter:blur(8px)}\n#content{padding:24px;flex:1}\n\n/* ── Sidebar ── */\n.sb-logo{padding:20px 18px 16px;border-bottom:1px solid var(--border)}\n.sb-logo h2{font-size:14px;font-weight:700;color:var(--primary);letter-spacing:.5px}\n.sb-logo p{font-size:11px;color:var(--muted);margin-top:2px}\n.sb-nav{padding:12px 8px;flex:1}\n.nav-item{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:8px;font-size:13px;font-weight:500;color:var(--muted);cursor:pointer;transition:all .15s;border:none;background:none;width:100%;text-align:left}\n.nav-item:hover{background:rgba(99,102,241,.1);color:var(--text)}\n.nav-item.active{background:rgba(99,102,241,.18);color:var(--primary)}\n.nav-icon{font-size:16px;width:20px;text-align:center}\n.sb-footer{padding:14px 16px;border-top:1px solid var(--border);font-size:11px;color:var(--muted)}\n.sb-user{font-weight:600;color:var(--text);margin-bottom:2px;font-size:12px}\n.sb-role{display:inline-flex;align-items:center;padding:1px 7px;border-radius:10px;font-size:10px;font-weight:700;background:rgba(99,102,241,.2);color:var(--primary)}\n\n/* ── Cards ── */\n.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px}\n.stat-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:18px 20px}\n.stat-label{font-size:11px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.6px;margin-bottom:10px}\n.stat-val{font-size:28px;font-weight:700;line-height:1}\n.stat-sub{font-size:11px;color:var(--muted);margin-top:5px}\n.c-primary{color:var(--primary)} .c-success{color:var(--success)} .c-warn{color:var(--warn)} .c-danger{color:var(--danger)}\n\n/* ── Section ── */\n.section{background:var(--card);border:1px solid var(--border);border-radius:12px;margin-bottom:20px;overflow:hidden}\n.section-head{padding:14px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}\n.section-title{font-size:14px;font-weight:600}\n.section-body{padding:16px 20px}\n\n/* ── Table ── */\n.tbl-wrap{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-size:12.5px}\nth{text-align:left;padding:9px 12px;font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--border);background:rgba(255,255,255,.02);white-space:nowrap}\ntd{padding:10px 12px;border-bottom:1px solid rgba(51,65,85,.5);vertical-align:middle}\ntr:last-child td{border-bottom:none}\ntr:hover td{background:rgba(255,255,255,.02)}\n.email-cell{max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n/* ── Badges ── */\n.badge{display:inline-flex;align-items:center;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;white-space:nowrap}\n.badge-stable{background:rgba(16,185,129,.15);color:#10b981}\n.badge-fluct{background:rgba(245,158,11,.15);color:#f59e0b}\n.badge-high{background:rgba(239,68,68,.15);color:#ef4444}\n.badge-active{background:rgba(16,185,129,.12);color:#10b981}\n.badge-locked{background:rgba(239,68,68,.12);color:#ef4444}\n.badge-deact{background:rgba(100,116,139,.15);color:#64748b}\n.badge-noreport{background:rgba(245,158,11,.12);color:#f59e0b}\n.badge-root{background:rgba(168,85,247,.15);color:#a855f7}\n.badge-sub{background:rgba(99,102,241,.15);color:#818cf8}\n.badge-user{background:rgba(100,116,139,.12);color:#94a3b8}\n\n/* ── Buttons ── */\n.btn{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border-radius:7px;font-size:12px;font-weight:600;border:none;transition:all .15s}\n.btn-primary{background:var(--primary);color:#fff} .btn-primary:hover{background:#4f46e5}\n.btn-success{background:rgba(16,185,129,.15);color:var(--success);border:1px solid rgba(16,185,129,.3)} .btn-success:hover{background:rgba(16,185,129,.25)}\n.btn-danger{background:rgba(239,68,68,.12);color:var(--danger);border:1px solid rgba(239,68,68,.25)} .btn-danger:hover{background:rgba(239,68,68,.22)}\n.btn-ghost{background:rgba(255,255,255,.06);color:var(--muted);border:1px solid var(--border)} .btn-ghost:hover{background:rgba(255,255,255,.1);color:var(--text)}\n.btn-sm{padding:4px 10px;font-size:11px}\n\n/* ── Filters ── */\n.filter-bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px}\n.filter-bar input,.filter-bar select{background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px;outline:none}\n.filter-bar input:focus,.filter-bar select:focus{border-color:var(--primary)}\n.filter-bar input::placeholder{color:var(--muted)}\n.quick-filters{display:flex;gap:6px}\n.qf{padding:5px 12px;border-radius:6px;font-size:11px;font-weight:600;border:1px solid var(--border);background:transparent;color:var(--muted);cursor:pointer;transition:all .15s}\n.qf:hover,.qf.active{background:rgba(99,102,241,.15);color:var(--primary);border-color:rgba(99,102,241,.4)}\n\n/* ── Pagination ── */\n.pagination{display:flex;align-items:center;gap:8px;margin-top:14px;justify-content:flex-end;font-size:12px;color:var(--muted)}\n.pg-btn{padding:5px 10px;border-radius:6px;border:1px solid var(--border);background:transparent;color:var(--muted);cursor:pointer;font-size:12px}\n.pg-btn:hover:not(:disabled){background:rgba(255,255,255,.06);color:var(--text)}\n.pg-btn:disabled{opacity:.4;cursor:not-allowed}\n.pg-info{padding:0 4px}\n\n/* ── Charts ── */\n.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px}\n.chart-box{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:18px 20px}\n.chart-title{font-size:13px;font-weight:600;margin-bottom:14px}\n.chart-wrap{position:relative;height:200px}\n\n/* ── Modal ── */\n.overlay{position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:200;display:flex;align-items:center;justify-content:center;padding:20px}\n.modal{background:#1e293b;border:1px solid var(--border);border-radius:14px;width:100%;max-width:520px;overflow:hidden}\n.modal-head{padding:18px 22px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}\n.modal-title{font-size:15px;font-weight:700}\n.modal-close{background:none;border:none;color:var(--muted);font-size:20px;cursor:pointer;line-height:1}\n.modal-body{padding:20px 22px;max-height:70vh;overflow-y:auto}\n.modal-foot{padding:14px 22px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:10px}\n.form-group{margin-bottom:14px}\n.form-label{display:block;font-size:12px;font-weight:600;color:var(--muted);margin-bottom:5px}\n.form-input{width:100%;background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:8px 11px;font-size:13px;outline:none}\n.form-input:focus{border-color:var(--primary)}\n\n/* ── Toast ── */\n#toast-container{position:fixed;top:18px;right:18px;z-index:999;display:flex;flex-direction:column;gap:8px;pointer-events:none}\n.toast{padding:10px 16px;border-radius:8px;font-size:13px;font-weight:500;pointer-events:all;animation:slideIn .2s ease;max-width:320px}\n.toast-success{background:#064e3b;border:1px solid #10b981;color:#6ee7b7}\n.toast-error{background:#450a0a;border:1px solid #ef4444;color:#fca5a5}\n.toast-info{background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc}\n@keyframes slideIn{from{opacity:0;transform:translateX(20px)}to{opacity:1;transform:translateX(0)}}\n\n/* ── Login screen ── */\n#login-screen{display:flex;align-items:center;justify-content:center;min-height:100vh;width:100%;position:fixed;inset:0;background:var(--bg);z-index:100}\n.login-card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:36px;width:360px}\n.login-card h1{font-size:20px;font-weight:700;margin-bottom:4px}\n.login-card p{font-size:13px;color:var(--muted);margin-bottom:24px}\n\n/* ── Loading ── */\n.spinner{width:16px;height:16px;border:2px solid rgba(255,255,255,.2);border-top-color:#fff;border-radius:50%;animation:spin .6s linear infinite;display:inline-block}\n@keyframes spin{to{transform:rotate(360deg)}}\n.loading-row td{text-align:center;padding:32px;color:var(--muted)}\n.empty-row td{text-align:center;padding:32px;color:var(--muted)}\n\n/* ── Detail modal ── */\n.detail-row{display:flex;gap:8px;margin-bottom:8px;font-size:12.5px}\n.detail-key{color:var(--muted);min-width:130px;flex-shrink:0}\n.detail-val{color:var(--text)}\n.signal-list{display:flex;flex-direction:column;gap:4px;margin-top:4px}\n.signal-item{display:flex;gap:6px;font-size:12px}\n.signal-item::before{content:\"▸\";color:var(--primary);flex-shrink:0}\n.risk-section{margin-top:12px;padding-top:12px;border-top:1px solid var(--border)}\n.risk-section-title{font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;margin-bottom:6px}\n\n/* ── Timeline ── */\n.tl-item{display:flex;gap:12px;margin-bottom:10px;align-items:flex-start;font-size:12px}\n.tl-dot{width:10px;height:10px;border-radius:50%;margin-top:3px;flex-shrink:0}\n.tl-date{color:var(--muted);min-width:80px}\n.tl-info{flex:1}\n\n/* ── Responsive ── */\n@media(max-width:900px){\n  .stat-grid{grid-template-columns:repeat(2,1fr)}\n  .chart-grid{grid-template-columns:1fr}\n}\n@media(max-width:640px){\n  #sidebar{display:none}\n  #main{margin-left:0}\n  .stat-grid{grid-template-columns:1fr 1fr}\n}\n</style>\n</head>\n<body>\n\n<!-- Toast -->\n<div id=\"toast-container\"></div>\n\n<!-- Login Screen -->\n<div id=\"login-screen\">\n  <div class=\"login-card\">\n    <h1>🛡️ Admin Console</h1>\n    <p>StudySignal – Khu vực quản trị</p>\n    <div class=\"form-group\">\n      <label class=\"form-label\">Email</label>\n      <input id=\"login-email\" class=\"form-input\" type=\"email\" placeholder=\"admin@gmail.com\" autocomplete=\"email\"/>\n    </div>\n    <div class=\"form-group\">\n      <label class=\"form-label\">Mật khẩu</label>\n      <input id=\"login-pass\" class=\"form-input\" type=\"password\" placeholder=\"password\" autocomplete=\"current-password\"/>\n    </div>\n    <div id=\"login-err\" style=\"color:var(--danger);font-size:12px;margin-bottom:12px;display:none\"></div>\n    <button id=\"login-btn\" class=\"btn btn-primary\" style=\"width:100%;justify-content:center;padding:10px\" onclick=\"doLogin()\">\n      Đăng nhập\n    </button>\n  </div>\n</div>\n\n<!-- App Shell (hidden until logged in) -->\n<div id=\"app-shell\" style=\"display:none;width:100%\">\n\n  <!-- Sidebar -->\n  <div id=\"sidebar\">\n    <div class=\"sb-logo\">\n      <h2>📡 LSR Admin</h2>\n      <p>StudySignal Console</p>\n    </div>\n    <nav class=\"sb-nav\">\n      <button class=\"nav-item active\" onclick=\"navigate('dashboard')\" data-page=\"dashboard\">\n        <span class=\"nav-icon\">📊</span> Dashboard\n      </button>\n      <button class=\"nav-item\" onclick=\"navigate('users')\" data-page=\"users\">\n        <span class=\"nav-icon\">👥</span> Người dùng\n      </button>\n      <button class=\"nav-item\" onclick=\"navigate('entries')\" data-page=\"entries\">\n        <span class=\"nav-icon\">📋</span> Phiên học\n      </button>\n      <button class=\"nav-item\" onclick=\"navigate('reports')\" data-page=\"reports\">\n        <span class=\"nav-icon\">🤖</span> Báo cáo AI\n      </button>\n      <button class=\"nav-item\" onclick=\"navigate('apikeys')\" data-page=\"apikeys\">\n        <span class=\"nav-icon\">🔑</span> API Keys\n      </button>\n    </nav>\n    <div class=\"sb-footer\">\n      <div class=\"sb-user\" id=\"sb-user-name\">–</div>\n      <div style=\"margin:4px 0\"><span class=\"sb-role\" id=\"sb-user-role\">–</span></div>\n      <button class=\"btn btn-ghost btn-sm\" style=\"margin-top:8px\" onclick=\"doLogout()\">Đăng xuất</button>\n    </div>\n  </div>\n\n  <!-- Main -->\n  <div id=\"main\">\n    <div id=\"topbar\">\n      <div style=\"font-size:14px;font-weight:600\" id=\"topbar-title\">Dashboard</div>\n      <div style=\"font-size:12px;color:var(--muted)\" id=\"topbar-sub\">StudySignal Admin Console</div>\n    </div>\n    <div id=\"content\">\n      <!-- Pages injected here -->\n    </div>\n  </div>\n</div>\n\n<!-- Confirm Modal -->\n<div id=\"confirm-modal\" class=\"overlay\" style=\"display:none\">\n  <div class=\"modal\" style=\"max-width:400px\">\n    <div class=\"modal-head\">\n      <span class=\"modal-title\" id=\"confirm-title\">Xác nhận</span>\n      <button class=\"modal-close\" onclick=\"closeConfirm()\">×</button>\n    </div>\n    <div class=\"modal-body\">\n      <p id=\"confirm-msg\" style=\"font-size:13px;margin-bottom:14px\"></p>\n      <div id=\"confirm-reason-wrap\" class=\"form-group\" style=\"display:none\">\n        <label class=\"form-label\">Lý do (tùy chọn)</label>\n        <textarea id=\"confirm-reason\" class=\"form-input\" rows=\"2\" style=\"resize:vertical\" placeholder=\"Nhập lý do...\"></textarea>\n      </div>\n    </div>\n    <div class=\"modal-foot\">\n      <button class=\"btn btn-ghost\" onclick=\"closeConfirm()\">Hủy</button>\n      <button class=\"btn\" id=\"confirm-ok-btn\" onclick=\"confirmOk()\">Xác nhận</button>\n    </div>\n  </div>\n</div>\n\n<!-- Detail Modal -->\n<div id=\"detail-modal\" class=\"overlay\" style=\"display:none\">\n  <div class=\"modal\" style=\"max-width:600px\">\n    <div class=\"modal-head\">\n      <span class=\"modal-title\" id=\"detail-title\">Chi tiết</span>\n      <button class=\"modal-close\" onclick=\"document.getElementById('detail-modal').style.display='none'\">×</button>\n    </div>\n    <div class=\"modal-body\" id=\"detail-body\"></div>\n  </div>\n</div>\n\n<script>\n// ═══════════════════════════════════════════════════════════════════════════════\n// STATE\n// ═══════════════════════════════════════════════════════════════════════════════\nlet TOKEN = localStorage.getItem('lsr_admin_token') || ''\nlet ADMIN = JSON.parse(localStorage.getItem('lsr_admin_user') || 'null')\nlet currentPage = 'dashboard'\nlet confirmCallback = null\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// UTILS\n// ═══════════════════════════════════════════════════════════════════════════════\nfunction toast(msg, type='info') {\n  const el = document.createElement('div')\n  el.className = `toast toast-${type}`\n  el.textContent = msg\n  document.getElementById('toast-container').appendChild(el)\n  setTimeout(() => el.remove(), 3500)\n}\n\nasync function api(path, opts={}) {\n  const res = await fetch('/api/admin' + path, {\n    ...opts,\n    headers: { 'Authorization': 'Bearer ' + TOKEN, 'Content-Type': 'application/json', ...(opts.headers||{}) },\n  })\n  const data = await res.json()\n  if (!res.ok) throw new Error(data.message || 'Lỗi server')\n  return data\n}\n\nfunction fmtDate(d) {\n  if (!d) return '–'\n  return d.substring(0,10)\n}\nfunction fmtDateTime(d) {\n  if (!d) return '–'\n  return d.replace('T',' ').substring(0,16)\n}\nfunction riskBadge(r) {\n  if (!r) return '<span class=\"badge badge-noreport\">Chưa có</span>'\n  if (r==='Stable') return '<span class=\"badge badge-stable\">Ổn định</span>'\n  if (r==='Fluctuating') return '<span class=\"badge badge-fluct\">Dao động</span>'\n  if (r==='High Risk') return '<span class=\"badge badge-high\">Rủi ro cao</span>'\n  return `<span class=\"badge\">${r}</span>`\n}\nfunction statusBadge(isActive) {\n  return isActive ? '<span class=\"badge badge-active\">Hoạt động</span>' : '<span class=\"badge badge-deact\">Deactivated</span>'\n}\nfunction lockBadge(locked) {\n  return locked ? '<span class=\"badge badge-locked\">🔒 Bị khóa</span>' : '<span class=\"badge badge-active\">✓ Bình thường</span>'\n}\nfunction roleBadge(role) {\n  if (role==='rootadmin') return '<span class=\"badge badge-root\">rootadmin</span>'\n  if (role==='subadmin')  return '<span class=\"badge badge-sub\">subadmin</span>'\n  return '<span class=\"badge badge-user\">user</span>'\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// AUTH\n// ═══════════════════════════════════════════════════════════════════════════════\nasync function doLogin() {\n  const email = document.getElementById('login-email').value.trim()\n  const pass  = document.getElementById('login-pass').value\n  const errEl = document.getElementById('login-err')\n  const btn   = document.getElementById('login-btn')\n  errEl.style.display = 'none'\n  if (!email || !pass) { errEl.textContent='Vui lòng điền đầy đủ'; errEl.style.display='block'; return }\n  btn.disabled = true\n  btn.innerHTML = '<span class=\"spinner\"></span> Đang đăng nhập...'\n  try {\n    const res = await fetch('/api/auth/login', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({ email, password: pass })\n    })\n    const data = await res.json()\n    if (!res.ok) { throw new Error(data.message || 'Sai thông tin đăng nhập') }\n    if (!['rootadmin','subadmin'].includes(data.user?.role)) {\n      throw new Error('Bạn không có quyền truy cập khu vực quản trị')\n    }\n    TOKEN = data.token\n    ADMIN = data.user\n    localStorage.setItem('lsr_admin_token', TOKEN)\n    localStorage.setItem('lsr_admin_user', JSON.stringify(ADMIN))\n    initApp()\n  } catch(e) {\n    errEl.textContent = e.message\n    errEl.style.display = 'block'\n  } finally {\n    btn.disabled = false\n    btn.textContent = 'Đăng nhập'\n  }\n}\n\ndocument.getElementById('login-pass').addEventListener('keydown', e => { if(e.key==='Enter') doLogin() })\ndocument.getElementById('login-email').addEventListener('keydown', e => { if(e.key==='Enter') doLogin() })\n\nfunction doLogout() {\n  TOKEN = ''; ADMIN = null\n  localStorage.removeItem('lsr_admin_token')\n  localStorage.removeItem('lsr_admin_user')\n  // Clear password input every time login screen is shown\n  document.getElementById('login-pass').value = ''\n  document.getElementById('login-err').style.display = 'none'\n  document.getElementById('login-screen').style.display = 'flex'\n  document.getElementById('app-shell').style.display = 'none'\n}\n\nfunction initApp() {\n  document.getElementById('login-screen').style.display = 'none'\n  document.getElementById('app-shell').style.display = 'block'\n  document.getElementById('sb-user-name').textContent = ADMIN?.full_name || ADMIN?.email || '–'\n  document.getElementById('sb-user-role').textContent = ADMIN?.role || '–'\n  navigate('dashboard')\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// NAVIGATION\n// ═══════════════════════════════════════════════════════════════════════════════\nfunction navigate(page) {\n  currentPage = page\n  document.querySelectorAll('.nav-item').forEach(el => el.classList.toggle('active', el.dataset.page === page))\n  const titles = { dashboard:'Dashboard', users:'Quản lý Người dùng', entries:'Quản lý Phiên học', reports:'Báo cáo AI', apikeys:'API Keys' }\n  document.getElementById('topbar-title').textContent = titles[page] || page\n  const pages = { dashboard: renderDashboard, users: renderUsers, entries: renderEntries, reports: renderReports, apikeys: renderApiKeys }\n  if (pages[page]) pages[page]()\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// CONFIRM MODAL\n// ═══════════════════════════════════════════════════════════════════════════════\nfunction openConfirm(title, msg, cb, showReason=false, btnClass='btn-danger') {\n  document.getElementById('confirm-title').textContent = title\n  document.getElementById('confirm-msg').textContent = msg\n  document.getElementById('confirm-reason-wrap').style.display = showReason ? 'block' : 'none'\n  document.getElementById('confirm-reason').value = ''\n  const okBtn = document.getElementById('confirm-ok-btn')\n  okBtn.className = 'btn ' + btnClass\n  okBtn.textContent = 'Xác nhận'\n  confirmCallback = cb\n  document.getElementById('confirm-modal').style.display = 'flex'\n}\nfunction closeConfirm() { document.getElementById('confirm-modal').style.display = 'none'; confirmCallback = null }\nfunction confirmOk() {\n  const reason = document.getElementById('confirm-reason').value.trim()\n  const cb = confirmCallback   // capture BEFORE closeConfirm nulls it\n  closeConfirm()\n  if (cb) cb(reason)\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// DASHBOARD\n// ═══════════════════════════════════════════════════════════════════════════════\nlet dashCharts = {}\nlet dashState = { from:'', to:'', timelineUserId:'' }\n\nfunction renderDashboard() {\n  const today = new Date(Date.now()+7*3600000).toISOString().split('T')[0]\n  const d30 = new Date(Date.now()+7*3600000-29*86400000).toISOString().split('T')[0]\n  dashState.from = dashState.from || d30\n  dashState.to   = dashState.to   || today\n\n  document.getElementById('content').innerHTML = `\n    <div style=\"margin-bottom:20px\">\n      <div class=\"filter-bar\">\n        <div class=\"quick-filters\">\n          <button class=\"qf\" onclick=\"setDashRange(0)\">Hôm nay</button>\n          <button class=\"qf\" onclick=\"setDashRange(6)\">7 ngày</button>\n          <button class=\"qf active\" onclick=\"setDashRange(29)\">30 ngày</button>\n          <button class=\"qf\" onclick=\"setDashRange(89)\">90 ngày</button>\n        </div>\n        <input type=\"date\" id=\"dash-from\" value=\"${dashState.from}\" onchange=\"dashState.from=this.value\" style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n        <input type=\"date\" id=\"dash-to\" value=\"${dashState.to}\" onchange=\"dashState.to=this.value\" style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n        <button class=\"btn btn-primary btn-sm\" onclick=\"loadDashStats()\">Áp dụng</button>\n      </div>\n    </div>\n\n    <div class=\"stat-grid\" id=\"dash-stats\">\n      ${[0,1,2,3].map(()=>`<div class=\"stat-card\"><div class=\"stat-label\">…</div><div class=\"stat-val\" style=\"color:var(--muted)\">–</div></div>`).join('')}\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-box\">\n        <div class=\"chart-title\">📈 Người dùng mới theo ngày</div>\n        <div class=\"chart-wrap\"><canvas id=\"chart-users\"></canvas></div>\n      </div>\n      <div class=\"chart-box\">\n        <div class=\"chart-title\">🥧 Phân bố rủi ro</div>\n        <div class=\"chart-wrap\"><canvas id=\"chart-risk\"></canvas></div>\n      </div>\n    </div>\n\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">📅 Số phiên học theo ngày</span>\n      </div>\n      <div class=\"section-body\">\n        <div style=\"position:relative;height:160px\"><canvas id=\"chart-sessions\"></canvas></div>\n      </div>\n    </div>\n\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">👤 Timeline người dùng</span>\n      </div>\n      <div class=\"section-body\">\n        <div class=\"filter-bar\" style=\"margin-bottom:14px\">\n          <input id=\"tl-user-id\" placeholder=\"Nhập User ID...\" style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px;width:160px\"/>\n          <button class=\"btn btn-primary btn-sm\" onclick=\"loadTimeline()\">Xem Timeline</button>\n        </div>\n        <div id=\"timeline-content\" style=\"font-size:12px;color:var(--muted)\">Nhập User ID để xem timeline.</div>\n      </div>\n    </div>\n  `\n  loadDashStats()\n}\n\nasync function loadDashStats() {\n  const from = document.getElementById('dash-from')?.value || dashState.from\n  const to   = document.getElementById('dash-to')?.value   || dashState.to\n  dashState.from = from; dashState.to = to\n\n  try {\n    const d = await api(`/stats?from=${from}&to=${to}`)\n    document.getElementById('dash-stats').innerHTML = `\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Tổng người dùng</div>\n        <div class=\"stat-val c-primary\">${d.total_users}</div>\n        <div class=\"stat-sub\">tài khoản user</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Người dùng mới</div>\n        <div class=\"stat-val c-success\">${d.new_users_count}</div>\n        <div class=\"stat-sub\">${from} → ${to}</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Người dùng hoạt động</div>\n        <div class=\"stat-val c-warn\">${d.active_users_count}</div>\n        <div class=\"stat-sub\">có phiên học trong kỳ</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">High Risk</div>\n        <div class=\"stat-val c-danger\">${d.high_risk_count}</div>\n        <div class=\"stat-sub\">người dùng cần chú ý</div>\n      </div>\n    `\n\n    // Destroy old charts\n    Object.values(dashCharts).forEach(c => c.destroy())\n    dashCharts = {}\n\n    // Users chart\n    const uc = document.getElementById('chart-users')\n    if (uc) {\n      dashCharts.users = new Chart(uc, {\n        type:'line',\n        data:{\n          labels: d.daily_new_users.map(r=>r.date.substring(5)),\n          datasets:[{label:'Người dùng mới',data:d.daily_new_users.map(r=>r.count),\n            borderColor:'#6366f1',backgroundColor:'rgba(99,102,241,.12)',fill:true,tension:.3,pointRadius:3}]\n        },\n        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},\n          scales:{x:{ticks:{color:'#94a3b8',font:{size:10}},grid:{color:'rgba(255,255,255,.05)'}},\n                  y:{ticks:{color:'#94a3b8',font:{size:10}},grid:{color:'rgba(255,255,255,.05)'},beginAtZero:true}}}\n      })\n    }\n\n    // Risk pie\n    const rc = document.getElementById('chart-risk')\n    if (rc && d.risk_distribution.length) {\n      const labelMap = {'Stable':'Ổn định','Fluctuating':'Dao động','High Risk':'Rủi ro cao'}\n      const colorMap = {'Stable':'#10b981','Fluctuating':'#f59e0b','High Risk':'#ef4444'}\n      dashCharts.risk = new Chart(rc, {\n        type:'doughnut',\n        data:{\n          labels: d.risk_distribution.map(r=>labelMap[r.risk_level]||r.risk_level),\n          datasets:[{data:d.risk_distribution.map(r=>r.count),\n            backgroundColor:d.risk_distribution.map(r=>colorMap[r.risk_level]||'#94a3b8'),\n            borderColor:'#1e293b',borderWidth:2}]\n        },\n        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#94a3b8',font:{size:11}}}}}\n      })\n    } else if (rc) {\n      const ctx = rc.getContext('2d')\n      ctx.fillStyle='#94a3b8'; ctx.font='13px Inter'; ctx.textAlign='center'\n      ctx.fillText('Chưa có dữ liệu', rc.width/2, rc.height/2)\n    }\n\n    // Sessions bar\n    const sc = document.getElementById('chart-sessions')\n    if (sc) {\n      dashCharts.sessions = new Chart(sc, {\n        type:'bar',\n        data:{\n          labels:d.daily_sessions.map(r=>r.date.substring(5)),\n          datasets:[{label:'Phiên học',data:d.daily_sessions.map(r=>r.count),\n            backgroundColor:'rgba(16,185,129,.5)',borderColor:'#10b981',borderWidth:1,borderRadius:3}]\n        },\n        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},\n          scales:{x:{ticks:{color:'#94a3b8',font:{size:10}},grid:{color:'rgba(255,255,255,.05)'}},\n                  y:{ticks:{color:'#94a3b8',font:{size:10}},grid:{color:'rgba(255,255,255,.05)'},beginAtZero:true}}}\n      })\n    }\n  } catch(e) { toast(e.message, 'error') }\n}\n\nfunction setDashRange(days) {\n  const to  = new Date(Date.now()+7*3600000).toISOString().split('T')[0]\n  const from= new Date(Date.now()+7*3600000-days*86400000).toISOString().split('T')[0]\n  document.getElementById('dash-from').value = from\n  document.getElementById('dash-to').value   = to\n  dashState.from = from; dashState.to = to\n  document.querySelectorAll('.qf').forEach(b=>b.classList.remove('active'))\n  event.target.classList.add('active')\n  loadDashStats()\n}\n\nasync function loadTimeline() {\n  const uid = document.getElementById('tl-user-id').value.trim()\n  if (!uid) { toast('Nhập User ID','error'); return }\n  const el = document.getElementById('timeline-content')\n  el.innerHTML = '<span class=\"spinner\"></span> Đang tải...'\n  try {\n    const d = await api(`/user-timeline/${uid}?from=${dashState.from}&to=${dashState.to}`)\n    if (!d.timeline.length) { el.innerHTML='<span style=\"color:var(--muted)\">Không có dữ liệu trong kỳ này.</span>'; return }\n    const colorMap = {'Stable':'#10b981','Fluctuating':'#f59e0b','High Risk':'#ef4444'}\n    el.innerHTML = `\n      <div style=\"margin-bottom:12px;font-size:12px\">\n        <strong>${d.user.email}</strong> &nbsp;|&nbsp; ${d.user.full_name||'–'} &nbsp;|&nbsp; ${roleBadge(d.user.role)}\n      </div>\n      <div style=\"display:flex;flex-wrap:wrap;gap:6px\">\n        ${d.timeline.map(t=>`\n          <div title=\"${t.session_date} P${t.session_number} – ${t.risk_level||'?'}\" style=\"\n            width:36px;height:36px;border-radius:6px;display:flex;align-items:center;justify-content:center;\n            font-size:10px;font-weight:700;cursor:default;\n            background:${colorMap[t.risk_level]||'#334155'}22;\n            border:1px solid ${colorMap[t.risk_level]||'#334155'};\n            color:${colorMap[t.risk_level]||'#94a3b8'}\n          \">${t.session_date.substring(5)}</div>\n        `).join('')}\n      </div>\n      <div style=\"display:flex;gap:14px;margin-top:10px;font-size:11px;color:var(--muted)\">\n        <span style=\"color:#10b981\">■ Ổn định</span>\n        <span style=\"color:#f59e0b\">■ Dao động</span>\n        <span style=\"color:#ef4444\">■ Rủi ro cao</span>\n        <span style=\"color:#334155\">■ Chưa có báo cáo</span>\n      </div>\n    `\n  } catch(e) { el.innerHTML=`<span style=\"color:var(--danger)\">${e.message}</span>` }\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// USERS PAGE\n// ═══════════════════════════════════════════════════════════════════════════════\nlet usersState = { page:1, search:'', filter:'all', total:0, total_pages:1, limit:15 }\n\nfunction renderUsers() {\n  document.getElementById('content').innerHTML = `\n    <div class=\"filter-bar\">\n      <input id=\"u-search\" placeholder=\"Tìm theo email...\" value=\"${usersState.search}\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px;width:220px\"\n        oninput=\"usersState.search=this.value\" onkeydown=\"if(event.key==='Enter'){usersState.page=1;loadUsers()}\"/>\n      <select id=\"u-filter\" onchange=\"usersState.filter=this.value;usersState.page=1;loadUsers()\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px\">\n        <option value=\"all\" ${usersState.filter==='all'?'selected':''}>Tất cả</option>\n        <option value=\"active\" ${usersState.filter==='active'?'selected':''}>Đang hoạt động</option>\n        <option value=\"locked\" ${usersState.filter==='locked'?'selected':''}>Bị khóa</option>\n      </select>\n      <button class=\"btn btn-primary btn-sm\" onclick=\"usersState.page=1;loadUsers()\">Tìm kiếm</button>\n    </div>\n\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">👥 Danh sách người dùng</span>\n        <span id=\"u-count\" style=\"font-size:12px;color:var(--muted)\"></span>\n      </div>\n      <div class=\"tbl-wrap\">\n        <table>\n          <thead><tr>\n            <th>ID</th><th>Email</th><th>Họ tên</th><th>Role</th><th>Trạng thái</th>\n            <th>Phiên học</th><th>Hoạt động cuối</th><th>Ngày tạo</th>\n            <th>MK tạm</th>\n            ${ADMIN?.role==='rootadmin'?'<th>Hành động</th>':''}\n          </tr></thead>\n          <tbody id=\"u-tbody\"><tr class=\"loading-row\"><td colspan=\"10\"><span class=\"spinner\"></span></td></tr></tbody>\n        </table>\n      </div>\n      <div class=\"section-body\" style=\"padding-top:0\">\n        <div class=\"pagination\" id=\"u-pagination\"></div>\n      </div>\n    </div>\n  `\n  loadUsers()\n}\n\nasync function loadUsers() {\n  const s = usersState\n  try {\n    const d = await api(`/users?page=${s.page}&limit=${s.limit}&search=${encodeURIComponent(s.search)}&filter=${s.filter}`)\n    usersState.total = d.total; usersState.total_pages = d.total_pages\n    document.getElementById('u-count').textContent = `${d.total} người dùng`\n    const cols = ADMIN?.role==='rootadmin' ? 10 : 9\n    const tbody = document.getElementById('u-tbody')\n    if (!d.users.length) {\n      tbody.innerHTML = `<tr class=\"empty-row\"><td colspan=\"${cols}\">Không có dữ liệu</td></tr>`\n    } else {\n      tbody.innerHTML = d.users.map(u => {\n        // Show temp password only when must_change_password=1 (not yet changed)\n        const tempPwDisplay = (u.must_change_password && u.temp_password)\n          ? `<code style=\"font-size:11px;color:#f59e0b;background:rgba(245,158,11,.1);padding:2px 6px;border-radius:4px;border:1px solid rgba(245,158,11,.3);letter-spacing:1px\">${u.temp_password}</code>`\n          : '<span style=\"color:var(--muted)\">–</span>'\n        return `\n        <tr>\n          <td style=\"color:var(--muted);font-size:11px\">#${u.id}</td>\n          <td class=\"email-cell\" title=\"${u.email}\">${u.email}</td>\n          <td>${u.full_name||'–'}</td>\n          <td>${roleBadge(u.role)}</td>\n          <td>${lockBadge(u.is_locked)}</td>\n          <td style=\"text-align:center\">${u.sessions_count||0}</td>\n          <td>${fmtDate(u.last_active)}</td>\n          <td>${fmtDate(u.created_at)}</td>\n          <td>${tempPwDisplay}</td>\n          ${ADMIN?.role==='rootadmin' ? `<td style=\"display:flex;gap:6px;flex-wrap:wrap\">\n            ${u.is_locked\n              ? `<button class=\"btn btn-success btn-sm\" onclick=\"unlockUser(${u.id},'${u.email}')\">🔓 Mở khóa</button>`\n              : `<button class=\"btn btn-danger btn-sm\" onclick=\"lockUser(${u.id},'${u.email}')\">🔒 Khóa</button>`\n            }\n            <button class=\"btn btn-ghost btn-sm\" onclick=\"resetPassword(${u.id},'${u.email}','${(u.full_name||'').replace(/'/g,\"\\\\'\")}')\">🔑 Reset MK</button>\n          </td>` : ''}\n        </tr>\n      `}).join('')\n    }\n    renderPagination('u-pagination', s.page, s.total_pages, p=>{usersState.page=p;loadUsers()})\n  } catch(e) { toast(e.message,'error') }\n}\n\nfunction lockUser(id, email) {\n  openConfirm('Khóa tài khoản', `Bạn có chắc muốn khóa tài khoản \"${email}\"?`, async (reason)=>{\n    try {\n      await api(`/users/${id}/lock`, {method:'POST', body:JSON.stringify({reason})})\n      toast('Đã khóa tài khoản', 'success'); loadUsers()\n    } catch(e) { toast(e.message,'error') }\n  }, true, 'btn-danger')\n}\n\nfunction unlockUser(id, email) {\n  openConfirm('Mở khóa tài khoản', `Bạn có chắc muốn mở khóa tài khoản \"${email}\"?`, async ()=>{\n    try {\n      await api(`/users/${id}/unlock`, {method:'POST', body:JSON.stringify({})})\n      toast('Đã mở khóa tài khoản', 'success'); loadUsers()\n    } catch(e) { toast(e.message,'error') }\n  }, false, 'btn-success')\n}\n\n// ── Reset password (rootadmin only) ──────────────────────────────────────────\nfunction resetPassword(id, email, fullName) {\n  openConfirm(\n    'Reset mật khẩu',\n    `Reset mật khẩu cho \"${email}\"? Mật khẩu tạm thời sẽ được tạo tự động.`,\n    async () => {\n      try {\n        const d = await api(`/users/${id}/reset-password`, {method:'POST', body:JSON.stringify({})})\n        showResetResult(d.data)\n      } catch(e) { toast(e.message,'error') }\n    },\n    false, 'btn-primary'\n  )\n}\n\n// ── Show reset result modal ───────────────────────────────────────────────────\nfunction showResetResult(data) {\n  document.getElementById('detail-title').textContent = '🔑 Mật khẩu tạm thời'\n  document.getElementById('detail-body').innerHTML = `\n    <div style=\"margin-bottom:14px;padding:12px;background:rgba(99,102,241,.1);border:1px solid rgba(99,102,241,.3);border-radius:8px\">\n      <div style=\"font-size:12px;color:var(--muted);margin-bottom:4px\">Học sinh</div>\n      <div style=\"font-size:14px;font-weight:700\">${data.full_name||data.email}</div>\n      <div style=\"font-size:12px;color:var(--muted)\">${data.email}</div>\n    </div>\n    <div style=\"margin-bottom:14px\">\n      <div style=\"font-size:12px;color:var(--muted);margin-bottom:6px\">Mật khẩu tạm thời</div>\n      <div style=\"display:flex;align-items:center;gap:10px\">\n        <code id=\"temp-pw\" style=\"font-size:20px;font-weight:700;color:#f59e0b;letter-spacing:2px;background:rgba(245,158,11,.1);padding:8px 14px;border-radius:8px;border:1px solid rgba(245,158,11,.3)\">${data.temporary_password}</code>\n        <button class=\"btn btn-ghost btn-sm\" onclick=\"navigator.clipboard.writeText('${data.temporary_password}').then(()=>toast('Đã sao chép','success'))\">📋 Sao chép</button>\n      </div>\n    </div>\n    <div style=\"padding:10px 12px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.2);border-radius:8px;font-size:12px;color:#f59e0b\">\n      ⚠️ Yêu cầu học sinh đổi mật khẩu ngay sau khi đăng nhập bằng mật khẩu tạm thời này.\n    </div>\n  `\n  document.getElementById('detail-modal').style.display = 'flex'\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// ENTRIES PAGE\n// ═══════════════════════════════════════════════════════════════════════════════\nlet entriesState = { page:1, search:'', filter:'all', from:'', to:'', total:0, total_pages:1, limit:15 }\n\nfunction renderEntries() {\n  const today = new Date(Date.now()+7*3600000).toISOString().split('T')[0]\n  const d30   = new Date(Date.now()+7*3600000-29*86400000).toISOString().split('T')[0]\n  entriesState.from = entriesState.from || d30\n  entriesState.to   = entriesState.to   || today\n\n  document.getElementById('content').innerHTML = `\n    <div class=\"filter-bar\">\n      <input id=\"e-search\" placeholder=\"Tìm theo email...\" value=\"${entriesState.search}\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px;width:200px\"\n        oninput=\"entriesState.search=this.value\" onkeydown=\"if(event.key==='Enter'){entriesState.page=1;loadEntries()}\"/>\n      <select id=\"e-filter\" onchange=\"entriesState.filter=this.value;entriesState.page=1;loadEntries()\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px\">\n        <option value=\"all\">Tất cả</option>\n        <option value=\"active\">Đang hoạt động</option>\n        <option value=\"no_report\">Chưa có báo cáo AI</option>\n      </select>\n      <input type=\"date\" id=\"e-from\" value=\"${entriesState.from}\" onchange=\"entriesState.from=this.value\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n      <input type=\"date\" id=\"e-to\" value=\"${entriesState.to}\" onchange=\"entriesState.to=this.value\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n      <button class=\"btn btn-primary btn-sm\" onclick=\"entriesState.page=1;loadEntries()\">Lọc</button>\n    </div>\n\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">📋 Danh sách phiên học</span>\n        <span id=\"e-count\" style=\"font-size:12px;color:var(--muted)\"></span>\n      </div>\n      <div class=\"tbl-wrap\">\n        <table>\n          <thead><tr>\n            <th>Phiên học</th><th>Người dùng</th>\n            <th>Giờ học</th><th>Focus</th><th>Dropout</th>\n            <th>Rủi ro</th><th>Trạng thái</th><th>Báo cáo AI</th>\n          </tr></thead>\n          <tbody id=\"e-tbody\"><tr class=\"loading-row\"><td colspan=\"8\"><span class=\"spinner\"></span></td></tr></tbody>\n        </table>\n      </div>\n      <div class=\"section-body\" style=\"padding-top:0\">\n        <div class=\"pagination\" id=\"e-pagination\"></div>\n      </div>\n    </div>\n  `\n  loadEntries()\n}\n\nasync function loadEntries() {\n  const s = entriesState\n  try {\n    const d = await api(`/entries?page=${s.page}&limit=${s.limit}&user_email=${encodeURIComponent(s.search)}&filter=${s.filter}&from=${s.from}&to=${s.to}`)\n    entriesState.total = d.total; entriesState.total_pages = d.total_pages\n    document.getElementById('e-count').textContent = `${d.total} phiên học`\n    const tbody = document.getElementById('e-tbody')\n    if (!d.entries.length) {\n      tbody.innerHTML = '<tr class=\"empty-row\"><td colspan=\"8\">Không có dữ liệu</td></tr>'\n    } else {\n      tbody.innerHTML = d.entries.map(e => {\n        const sd = e.session_date ? String(e.session_date).substring(0,10).replace(/-/g,'/') : '–'\n        const sessionLabel = `${sd} - Phiên ${e.session_number||1}`\n        return `\n        <tr>\n          <td style=\"white-space:nowrap;font-weight:500\">${sessionLabel}</td>\n          <td class=\"email-cell\" title=\"${e.user_email}\">${e.user_email}</td>\n          <td>${(+e.study_hours||0).toFixed(1)}h</td>\n          <td style=\"text-align:center\">${e.focus_level||'–'}/5</td>\n          <td style=\"text-align:center\">${e.dropout_feeling||'–'}/5</td>\n          <td>${riskBadge(e.risk_level)}</td>\n          <td>${statusBadge(e.is_active)}</td>\n          <td style=\"text-align:center\">${e.has_report ? '<span style=\"color:var(--success)\">✓</span>' : '<span style=\"color:var(--muted)\">–</span>'}</td>\n        </tr>\n      `}).join('')\n    }\n    renderPagination('e-pagination', s.page, s.total_pages, p=>{entriesState.page=p;loadEntries()})\n  } catch(e) { toast(e.message,'error') }\n}\n\n// Kept for compatibility but no longer exposed in UI\nfunction deactivateEntry(id) {\n  openConfirm('Deactivate phiên học', `Deactivate phiên học #${id}?`, async (reason)=>{\n    try {\n      await api(`/entries/${id}/deactivate`, {method:'POST', body:JSON.stringify({reason})})\n      toast('Đã deactivate phiên học','success'); loadEntries()\n    } catch(e) { toast(e.message,'error') }\n  }, true, 'btn-danger')\n}\nfunction reactivateEntry(id) {\n  openConfirm('Reactivate phiên học', `Reactivate phiên học #${id}?`, async ()=>{\n    try {\n      await api(`/entries/${id}/reactivate`, {method:'POST', body:JSON.stringify({})})\n      toast('Đã reactivate','success'); loadEntries()\n    } catch(e) { toast(e.message,'error') }\n  }, false, 'btn-success')\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// REPORTS PAGE\n// ═══════════════════════════════════════════════════════════════════════════════\nlet reportsState = { page:1, search:'', risk:'', from:'', to:'', total:0, total_pages:1, groupByUser:true }\n\nfunction renderReports() {\n  const today = new Date(Date.now()+7*3600000).toISOString().split('T')[0]\n  const d30   = new Date(Date.now()+7*3600000-29*86400000).toISOString().split('T')[0]\n  reportsState.from = reportsState.from || d30\n  reportsState.to   = reportsState.to   || today\n\n  document.getElementById('content').innerHTML = `\n    <div class=\"filter-bar\">\n      <input id=\"r-search\" placeholder=\"Tìm theo email...\" value=\"${reportsState.search}\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px;width:200px\"\n        oninput=\"reportsState.search=this.value\" onkeydown=\"if(event.key==='Enter'){reportsState.page=1;loadReports()}\"/>\n      <select id=\"r-risk\" onchange=\"reportsState.risk=this.value;reportsState.page=1;loadReports()\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:6px 11px;font-size:12px\">\n        <option value=\"\">Tất cả mức rủi ro</option>\n        <option value=\"Stable\">Ổn định</option>\n        <option value=\"Fluctuating\">Dao động</option>\n        <option value=\"High Risk\">Rủi ro cao</option>\n      </select>\n      <input type=\"date\" id=\"r-from\" value=\"${reportsState.from}\" onchange=\"reportsState.from=this.value\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n      <input type=\"date\" id=\"r-to\" value=\"${reportsState.to}\" onchange=\"reportsState.to=this.value\"\n        style=\"background:rgba(255,255,255,.05);border:1px solid var(--border);border-radius:7px;color:var(--text);padding:5px 10px;font-size:12px\"/>\n      <button class=\"btn btn-primary btn-sm\" onclick=\"reportsState.page=1;loadReports()\">Lọc</button>\n      <label style=\"display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);cursor:pointer;margin-left:4px\">\n        <input type=\"checkbox\" id=\"r-group\" ${reportsState.groupByUser?'checked':''} onchange=\"reportsState.groupByUser=this.checked;reportsState.page=1;loadReports()\" style=\"accent-color:var(--primary)\"/>\n        Nhóm theo người dùng\n      </label>\n    </div>\n\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">🤖 Danh sách báo cáo AI</span>\n        <span id=\"r-count\" style=\"font-size:12px;color:var(--muted)\"></span>\n      </div>\n      <div class=\"tbl-wrap\">\n        <table>\n          <thead><tr>\n            <th>ID</th><th>Ngày báo cáo</th><th>Phiên</th>\n            <th>Rủi ro</th><th>Vấn đề cốt lõi</th><th>Chi tiết</th>\n          </tr></thead>\n          <tbody id=\"r-tbody\"><tr class=\"loading-row\"><td colspan=\"6\"><span class=\"spinner\"></span></td></tr></tbody>\n        </table>\n      </div>\n      <div class=\"section-body\" style=\"padding-top:0\">\n        <div class=\"pagination\" id=\"r-pagination\"></div>\n      </div>\n    </div>\n  `\n  loadReports()\n}\n\nasync function loadReports() {\n  const s = reportsState\n  try {\n    const d = await api(`/reports?page=${s.page}&limit=12&user_email=${encodeURIComponent(s.search)}&risk_level=${encodeURIComponent(s.risk)}&from=${s.from}&to=${s.to}`)\n    reportsState.total = d.total; reportsState.total_pages = d.total_pages\n    document.getElementById('r-count').textContent = `${d.total} báo cáo`\n    const tbody = document.getElementById('r-tbody')\n    if (!d.reports.length) {\n      tbody.innerHTML = '<tr class=\"empty-row\"><td colspan=\"6\">Không có dữ liệu</td></tr>'\n    } else if (s.groupByUser) {\n      // Group reports by user — thead: ID | Ngày báo cáo | Phiên | Rủi ro | Vấn đề cốt lõi | Chi tiết (6 cols)\n      const grouped = {}\n      d.reports.forEach(r => {\n        const key = r.user_email\n        if (!grouped[key]) grouped[key] = { email: r.user_email, reports: [] }\n        grouped[key].reports.push(r)\n        window['_report_'+r.id] = r\n      })\n      const rows = []\n      Object.values(grouped).forEach(g => {\n        rows.push(`<tr style=\"background:rgba(99,102,241,0.08)\">\n          <td colspan=\"6\" style=\"padding:8px 12px\">\n            <div style=\"display:flex;align-items:center;justify-content:space-between\">\n              <span style=\"font-weight:700;font-size:13px;color:var(--primary)\">${g.email}</span>\n              <span style=\"font-size:11px;color:var(--muted)\">${g.reports.length} báo cáo</span>\n            </div>\n          </td>\n        </tr>`)\n        g.reports.forEach(r => {\n          const driver = r.primary_risk_driver ? String(r.primary_risk_driver).substring(0,55)+(String(r.primary_risk_driver).length>55?'…':'') : '–'\n          rows.push(`<tr>\n            <td style=\"color:var(--muted);font-size:11px;padding-left:24px\">#${r.id}</td>\n            <td>${fmtDate(r.report_date)}</td>\n            <td style=\"text-align:center\">P${r.session_number||1}</td>\n            <td>${riskBadge(r.risk_level)}</td>\n            <td style=\"max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:12px\" title=\"${r.primary_risk_driver||''}\">${driver}</td>\n            <td><button class=\"btn btn-ghost btn-sm\" onclick=\"showReportDetail(${r.id})\">Xem chi tiết</button></td>\n          </tr>`)\n        })\n      })\n      tbody.innerHTML = rows.join('')\n    } else {\n      tbody.innerHTML = d.reports.map(r => {\n        const driver = r.primary_risk_driver ? String(r.primary_risk_driver).substring(0,60)+(String(r.primary_risk_driver).length>60?'…':'') : '–'\n        window['_report_'+r.id] = r\n        return `\n          <tr>\n            <td style=\"color:var(--muted);font-size:11px\">#${r.id}</td>\n            <td>${fmtDate(r.report_date)}</td>\n            <td style=\"text-align:center\">P${r.session_number||1}</td>\n            <td>${riskBadge(r.risk_level)}</td>\n            <td style=\"max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:12px\" title=\"${r.primary_risk_driver||''}\">${driver}</td>\n            <td><button class=\"btn btn-ghost btn-sm\" onclick=\"showReportDetail(${r.id})\">Xem chi tiết</button></td>\n          </tr>\n        `\n      }).join('')\n    }\n    renderPagination('r-pagination', s.page, s.total_pages, p=>{reportsState.page=p;loadReports()})\n  } catch(e) { toast(e.message,'error') }\n}\n\nfunction showReportDetail(id) {\n  const r = window['_report_'+id]\n  if (!r) return\n  let signals = []\n  try { signals = JSON.parse(r.key_signals||'[]') } catch { signals = [] }\n  let plan = []\n  try { plan = JSON.parse(r.action_plan_48h||'[]') } catch { plan = [] }\n\n  const colorMap = {'Stable':'#10b981','Fluctuating':'#f59e0b','High Risk':'#ef4444'}\n  const accent = colorMap[r.risk_level] || '#94a3b8'\n\n  document.getElementById('detail-title').textContent = `Báo cáo AI #${r.id} – ${r.user_email}`\n  document.getElementById('detail-body').innerHTML = `\n    <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px\">\n      <div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Người dùng:</span><span class=\"detail-val\">${r.user_email}</span></div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Ngày báo cáo:</span><span class=\"detail-val\">${fmtDate(r.report_date)}</span></div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Phiên số:</span><span class=\"detail-val\">P${r.session_number||1}</span></div>\n        ${r.analyzed_by ? `<div class=\"detail-row\"><span class=\"detail-key\">Tên Model Dùng:</span><span class=\"detail-val\" style=\"color:var(--primary);font-weight:600\">${r.analyzed_by}${r.key_name ? ' <span style=\"color:var(--muted);font-weight:400;font-size:11px\">(' + r.key_name + ')</span>' : ''}</span></div>` : ''}\n      </div>\n      <div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Mức rủi ro:</span><span class=\"detail-val\">${riskBadge(r.risk_level)}</span></div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Giờ học:</span><span class=\"detail-val\">${(+r.study_hours||0).toFixed(1)}h</span></div>\n        <div class=\"detail-row\"><span class=\"detail-key\">Focus / Dropout:</span><span class=\"detail-val\">${r.focus_level||'–'}/5 · ${r.dropout_feeling||'–'}/5</span></div>\n      </div>\n    </div>\n\n    ${signals.length ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\" style=\"color:${accent}\">⚠️ Tín hiệu phát hiện</div>\n        <div class=\"signal-list\">${signals.map(s=>`<div class=\"signal-item\">${s}</div>`).join('')}</div>\n      </div>\n    ` : ''}\n\n    ${r.short_term_forecast ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\">🔮 Dự báo ngắn hạn</div>\n        <p style=\"font-size:12.5px;line-height:1.6;color:var(--text)\">${r.short_term_forecast}</p>\n      </div>\n    ` : ''}\n\n    ${r.primary_risk_driver ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\" style=\"color:${accent}\">🎯 Vấn đề cốt lõi</div>\n        <p style=\"font-size:12.5px;line-height:1.6;color:var(--text)\">${r.primary_risk_driver}</p>\n      </div>\n    ` : ''}\n\n    ${r.intervention_strategy ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\">💡 Chiến lược can thiệp</div>\n        <p style=\"font-size:12.5px;line-height:1.6;color:var(--text)\">${r.intervention_strategy}</p>\n      </div>\n    ` : ''}\n\n    ${plan.length ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\">📋 Kế hoạch 48h</div>\n        <ol style=\"padding-left:18px;display:flex;flex-direction:column;gap:4px\">\n          ${plan.map(s=>`<li style=\"font-size:12.5px;line-height:1.6;color:var(--text)\">${s}</li>`).join('')}\n        </ol>\n      </div>\n    ` : ''}\n\n    ${r.monitoring_protocol ? `\n      <div class=\"risk-section\">\n        <div class=\"risk-section-title\">🔔 Giao thức giám sát</div>\n        <p style=\"font-size:12.5px;line-height:1.6;color:var(--text)\">${r.monitoring_protocol}</p>\n      </div>\n    ` : ''}\n  `\n  document.getElementById('detail-modal').style.display = 'flex'\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// API KEYS PAGE\n// ═══════════════════════════════════════════════════════════════════════════════\nconst KEY_NAMES = ['March', 'April', 'May', 'June', 'July']\nconst MODEL_LIMITS = {\n  // Nguồn: Google AI Studio (2026-04) — Free Tier thực tế\n  'gemini-3.1-flash-lite-preview': 500,   // 500 RPD ← QUOTA CAO NHẤT\n  'gemini-2.0-flash-lite':         200,   // 200 RPD\n  'gemini-2.0-flash':              200,   // 200 RPD\n  'gemini-2.5-flash':               20,   // 20 RPD (thấp hơn dự kiến)\n  'gemini-2.5-flash-lite':          20,   // 20 RPD\n}\nconst MODEL_LABELS = {\n  'gemini-2.5-flash-lite': 'Gemini 2.5 Flash Lite',\n  'gemini-3.1-flash-lite-preview': 'Gemini 3.1 Flash Lite',\n  'gemini-2.5-flash': 'Gemini 2.5 Flash',\n  'gemini-2.0-flash-lite': 'Gemini 2.0 Flash Lite',\n  'gemini-2.0-flash': 'Gemini 2.0 Flash',\n}\n\n// ─── state cho model config editor ────────────────────────────────────────────\nlet _modelConfigRows = []   // Array<{id,model_name,display_name,sort_order,enabled,timeout_ms,daily_limit,notes}>\nlet _apiSubTab = 'stats'    // 'stats' | 'config'\n\nfunction renderApiKeys() {\n  document.getElementById('content').innerHTML = `\n    <!-- Sub-tab bar -->\n    <div style=\"display:flex;gap:8px;margin-bottom:16px;border-bottom:1px solid var(--border);padding-bottom:10px\">\n      <button id=\"subtab-stats\"  class=\"btn btn-sm\" onclick=\"switchApiSubTab('stats')\"  style=\"font-size:12px\">📊 Thống kê sử dụng</button>\n      <button id=\"subtab-config\" class=\"btn btn-sm\" onclick=\"switchApiSubTab('config')\" style=\"font-size:12px\">⚙️ Cấu hình Model AI</button>\n      <div style=\"flex:1\"></div>\n      <button class=\"btn btn-primary btn-sm\" onclick=\"refreshApiTab()\" style=\"font-size:12px\">🔄 Làm mới</button>\n    </div>\n    <div id=\"apikeys-content\">\n      <div style=\"text-align:center;padding:40px;color:var(--muted)\"><span class=\"spinner\"></span> Đang tải...</div>\n    </div>\n  `\n  switchApiSubTab('stats')\n}\n\nfunction switchApiSubTab(tab) {\n  _apiSubTab = tab\n  const statsBtn  = document.getElementById('subtab-stats')\n  const configBtn = document.getElementById('subtab-config')\n  if (statsBtn)  { statsBtn.style.background  = tab==='stats'  ? 'var(--primary)' : ''; statsBtn.style.color  = tab==='stats'  ? '#fff' : '' }\n  if (configBtn) { configBtn.style.background = tab==='config' ? 'var(--primary)' : ''; configBtn.style.color = tab==='config' ? '#fff' : '' }\n  if (tab === 'stats')  loadApiKeys()\n  else                  loadModelConfig()\n}\n\nfunction refreshApiTab() {\n  if (_apiSubTab === 'stats') loadApiKeys()\n  else loadModelConfig()\n}\n\n// ─── STATS TAB ─────────────────────────────────────────────────────────────────\nasync function loadApiKeys() {\n  const el = document.getElementById('apikeys-content')\n  if (!el) return\n  el.innerHTML = `<div style=\"text-align:center;padding:40px;color:var(--muted)\"><span class=\"spinner\"></span> Đang tải...</div>`\n  try {\n    const [statsData, cfgData] = await Promise.all([\n      api('/model-stats'),\n      api('/model-config'),\n    ])\n    const today = new Date(Date.now()+7*3600000).toISOString().split('T')[0]\n    const stats = statsData.stats || {}\n\n    // Build ordered model list from DB config (reflects admin priority settings)\n    const cfgModels = (cfgData.models || [])\n    const orderedModels = cfgModels.length\n      ? cfgModels.map(m => m.model_name)\n      : Object.keys(MODEL_LABELS)\n\n    // Luôn hiển thị đủ 5 key columns (KEY_NAMES), thêm key lạ nếu có\n    const keySet = new Set()\n    Object.values(stats).forEach(byKey => Object.keys(byKey).forEach(k => keySet.add(k)))\n    // KEY_NAMES luôn xuất hiện, key ngoài danh sách thêm vào cuối\n    const allKeys = [...KEY_NAMES, ...[...keySet].filter(k => !KEY_NAMES.includes(k))]\n\n    // Build per-model limit map from DB config\n    const dbLimits = {}\n    const dbLabels = {}\n    cfgModels.forEach(m => {\n      dbLimits[m.model_name] = m.daily_limit\n      dbLabels[m.model_name] = m.display_name\n    })\n    const getLbl   = m => dbLabels[m] || MODEL_LABELS[m] || m\n    const getLimit = m => dbLimits[m] != null ? dbLimits[m] : (MODEL_LIMITS[m] != null ? MODEL_LIMITS[m] : null)\n\n    // Tính tổng usage hôm nay để quyết định hiển thị hay empty state\n    const totalUsageToday = Object.values(stats).reduce((s, byKey) =>\n      s + Object.values(byKey).reduce((a, b) => a + b, 0), 0)\n\n    let html = `<div style=\"font-size:12px;color:var(--muted);margin-bottom:16px\">📅 Số lượt sử dụng hôm nay: <strong style=\"color:var(--text)\">${today}</strong> &nbsp;·&nbsp; Làm mới theo ngày lúc 00:00 GMT+7</div>`\n\n    if (!orderedModels.length) {\n      html += `<div class=\"section\"><div class=\"section-body\" style=\"text-align:center;padding:32px;color:var(--muted)\">Chưa có dữ liệu sử dụng hôm nay</div></div>`\n    } else {\n      html += `\n        <div class=\"section\">\n          <div class=\"section-head\"><span class=\"section-title\">📊 Lượt dùng theo Model × API Key</span>\n            <span style=\"font-size:11px;color:var(--muted);margin-left:8px\">(thứ tự = độ ưu tiên hiện tại)</span>\n          </div>\n          <div class=\"tbl-wrap\"><table>\n            <thead><tr>\n              <th style=\"width:30px\">#</th>\n              <th>Model</th>\n              <th>Giới hạn/ngày</th>\n              ${allKeys.map(k=>`<th style=\"text-align:center\">${k}</th>`).join('')}\n              <th style=\"text-align:center\">Tổng</th>\n            </tr></thead><tbody>`\n\n      orderedModels.forEach((model, idx) => {\n        const byKey = stats[model] || {}\n        const limit = getLimit(model)\n        let rowTotal = 0\n        const cells = allKeys.map(k => {\n          const cnt = byKey[k] || 0\n          rowTotal += cnt\n          const pct = (limit && limit > 0) ? cnt/limit : 0\n          const color = pct >= 1 ? 'var(--danger)' : pct >= 0.7 ? 'var(--warn)' : (cnt > 0 ? 'var(--success)' : 'var(--muted)')\n          const display = limit ? `${cnt}/${limit}` : `${cnt}`\n          return `<td style=\"text-align:center;font-weight:600;color:${color}\">${display}</td>`\n        }).join('')\n        const totalColor = rowTotal > 0 ? 'var(--primary)' : 'var(--muted)'\n        const cfgRow = cfgModels.find(m => m.model_name === model)\n        const isEnabled = !cfgRow || cfgRow.enabled === 1\n        html += `<tr style=\"${!isEnabled ? 'opacity:0.45' : ''}\">\n          <td style=\"text-align:center;color:var(--muted);font-size:11px\">${idx+1}</td>\n          <td style=\"font-weight:600\">${getLbl(model)} ${!isEnabled ? '<span style=\"font-size:10px;color:var(--danger)\">[tắt]</span>' : ''}</td>\n          <td style=\"color:var(--muted)\">${limit != null ? limit+'/ngày' : '–'}</td>\n          ${cells}\n          <td style=\"text-align:center;font-weight:700;color:${totalColor}\">${rowTotal}</td>\n        </tr>`\n      })\n\n      html += `</tbody></table></div></div>`\n\n      // Per-key cards\n      html += `<div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px;margin-top:20px\">`\n      allKeys.forEach(keyName => {\n        let keyTotal = 0\n        const modelRows = orderedModels.map(model => {\n          const cnt = (stats[model]||{})[keyName] || 0\n          keyTotal += cnt\n          if (!cnt) return ''\n          const limit = getLimit(model)\n          const pct = (limit && limit > 0) ? cnt/limit : 0\n          const color = pct >= 1 ? 'var(--danger)' : pct >= 0.7 ? 'var(--warn)' : 'var(--success)'\n          return `<div style=\"display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px\">\n            <span style=\"color:var(--muted)\">${getLbl(model)}</span>\n            <span style=\"font-weight:700;color:${color}\">${cnt}${limit?'/'+limit:''}</span>\n          </div>`\n        }).join('')\n        html += `<div class=\"stat-card\">\n          <div class=\"stat-label\">🔑 ${keyName}</div>\n          <div class=\"stat-val c-primary\" style=\"font-size:22px;margin-bottom:10px\">${keyTotal} <span style=\"font-size:13px;color:var(--muted);font-weight:400\">lượt</span></div>\n          ${modelRows || '<div style=\"font-size:11px;color:var(--muted)\">Chưa dùng hôm nay</div>'}\n        </div>`\n      })\n      html += `</div>`\n    }\n    el.innerHTML = html\n  } catch(e) {\n    el.innerHTML = `<div class=\"section\"><div class=\"section-body\" style=\"color:var(--danger);padding:20px\">${e.message}</div></div>`\n  }\n}\n\n// ─── CONFIG TAB ────────────────────────────────────────────────────────────────\nasync function loadModelConfig() {\n  const el = document.getElementById('apikeys-content')\n  if (!el) return\n  el.innerHTML = `<div style=\"text-align:center;padding:40px;color:var(--muted)\"><span class=\"spinner\"></span> Đang tải cấu hình...</div>`\n  try {\n    const d = await api('/model-config')\n    _modelConfigRows = d.models || []\n    renderModelConfigEditor()\n  } catch(e) {\n    el.innerHTML = `<div class=\"section\"><div class=\"section-body\" style=\"color:var(--danger);padding:20px\">${e.message}</div></div>`\n  }\n}\n\nfunction renderModelConfigEditor() {\n  const el = document.getElementById('apikeys-content')\n  if (!el) return\n  const isRoot = ADMIN && ADMIN.role === 'rootadmin'\n\n  let rows = [..._modelConfigRows].sort((a,b) => a.sort_order - b.sort_order)\n\n  let html = `\n    <div class=\"section\">\n      <div class=\"section-head\">\n        <span class=\"section-title\">⚙️ Cấu hình Model AI</span>\n        <span style=\"font-size:11px;color:var(--muted);margin-left:8px\">Thứ tự ưu tiên = thứ tự thử khi phân tích</span>\n      </div>\n      <div class=\"section-body\" style=\"padding:0\">\n  `\n\n  if (!isRoot) {\n    html += `<div style=\"padding:16px;background:rgba(245,158,11,0.1);border-radius:8px;margin:16px;font-size:13px;color:var(--warn)\">\n      ⚠️ Chỉ rootadmin mới có thể chỉnh sửa cấu hình model.\n    </div>`\n  }\n\n  html += `\n    <div style=\"padding:12px 16px;font-size:12px;color:var(--muted);background:rgba(99,102,241,0.06);border-bottom:1px solid var(--border)\">\n      💡 <strong>Hướng dẫn:</strong>\n      Kéo hàng để sắp xếp thứ tự ưu tiên — model ở trên cùng được thử trước.\n      Tắt model để loại khỏi vòng thử. Timeout: thời gian chờ tối đa mỗi lần gọi (5–60s).\n      ${isRoot ? '' : '&nbsp;<em>Chỉ rootadmin mới có thể lưu thay đổi.</em>'}\n    </div>\n    <div id=\"model-config-list\" style=\"padding:8px 12px\">\n  `\n\n  rows.forEach((m, idx) => {\n    const enabledChk = m.enabled === 1 ? 'checked' : ''\n    const timeoutSec = Math.round(m.timeout_ms / 1000)\n    const priorityLabel = idx === 0 ? '<span style=\"font-size:10px;font-weight:700;color:#818cf8;background:rgba(129,140,248,0.12);padding:2px 7px;border-radius:10px\">PRIMARY</span>'\n                        : idx === 1 ? '<span style=\"font-size:10px;font-weight:700;color:#22d3ee;background:rgba(34,211,238,0.1);padding:2px 7px;border-radius:10px\">FALLBACK</span>'\n                        : `<span style=\"font-size:10px;color:var(--muted);background:rgba(255,255,255,0.05);padding:2px 7px;border-radius:10px\">BACKUP ${idx}</span>`\n    const disabledAttr = isRoot ? '' : 'disabled'\n\n    html += `\n      <div class=\"model-cfg-row\" data-id=\"${m.id}\" data-idx=\"${idx}\"\n           draggable=\"${isRoot}\"\n           style=\"display:flex;align-items:center;gap:10px;padding:10px 8px;border-radius:10px;\n                  margin-bottom:6px;background:var(--bg-card,rgba(255,255,255,0.03));\n                  border:1px solid var(--border);transition:opacity .2s;\n                  ${m.enabled !== 1 ? 'opacity:0.5' : ''}\"\n           ondragstart=\"mcDragStart(event)\" ondragover=\"mcDragOver(event)\"\n           ondrop=\"mcDrop(event)\" ondragend=\"mcDragEnd(event)\">\n\n        <!-- Drag handle -->\n        <div title=\"Kéo để sắp xếp\" style=\"cursor:${isRoot?'grab':'default'};color:var(--muted);font-size:16px;flex-shrink:0;user-select:none\">⠿</div>\n\n        <!-- Priority badge -->\n        <div style=\"width:72px;flex-shrink:0;text-align:center\">${priorityLabel}</div>\n\n        <!-- Sort order input -->\n        <div style=\"flex-shrink:0;text-align:center\">\n          <label style=\"font-size:10px;color:var(--muted);display:block;margin-bottom:2px\">Thứ tự</label>\n          <input type=\"number\" class=\"mc-order\" data-id=\"${m.id}\"\n            value=\"${m.sort_order}\" min=\"1\" max=\"99\" step=\"1\" ${disabledAttr}\n            style=\"width:46px;padding:3px 4px;border-radius:6px;border:1px solid var(--border);\n                   background:var(--bg-input,rgba(255,255,255,0.06));color:var(--text);\n                   font-size:12px;text-align:center\"\n            onchange=\"mcSyncFromInputs()\">\n        </div>\n\n        <!-- Model name & daily limit -->\n        <div style=\"flex:1;min-width:0\">\n          <div style=\"font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis\">${m.display_name}</div>\n          <div style=\"font-size:11px;color:var(--muted);margin-top:2px\">${m.model_name}${m.daily_limit ? ' · '+m.daily_limit+' req/ngày' : ''}</div>\n        </div>\n\n        <!-- Timeout -->\n        <div style=\"flex-shrink:0;text-align:center\">\n          <label style=\"font-size:10px;color:var(--muted);display:block;margin-bottom:2px\">Timeout (s)</label>\n          <input type=\"number\" class=\"mc-timeout\" data-id=\"${m.id}\"\n            value=\"${timeoutSec}\" min=\"5\" max=\"60\" step=\"1\" ${disabledAttr}\n            style=\"width:56px;padding:3px 6px;border-radius:6px;border:1px solid var(--border);\n                   background:var(--bg-input,rgba(255,255,255,0.06));color:var(--text);\n                   font-size:12px;text-align:center\">\n        </div>\n\n        <!-- Notes -->\n        <div style=\"flex:0 0 140px\">\n          <label style=\"font-size:10px;color:var(--muted);display:block;margin-bottom:2px\">Ghi chú</label>\n          <input type=\"text\" class=\"mc-notes\" data-id=\"${m.id}\"\n            value=\"${(m.notes||'').replace(/\"/g,'&quot;')}\"\n            placeholder=\"Ghi chú...\" maxlength=\"100\" ${disabledAttr}\n            style=\"width:100%;padding:3px 6px;border-radius:6px;border:1px solid var(--border);\n                   background:var(--bg-input,rgba(255,255,255,0.06));color:var(--text);font-size:12px;box-sizing:border-box\">\n        </div>\n\n        <!-- Enabled toggle -->\n        <div style=\"flex-shrink:0;text-align:center\">\n          <label style=\"font-size:10px;color:var(--muted);display:block;margin-bottom:4px\">Bật</label>\n          <label class=\"toggle-label\" style=\"cursor:${isRoot?'pointer':'default'}\">\n            <input type=\"checkbox\" class=\"mc-enabled\" data-id=\"${m.id}\" ${enabledChk} ${disabledAttr}\n              onchange=\"mcToggleEnabled(this)\">\n            <span class=\"toggle-slider\"></span>\n          </label>\n        </div>\n      </div>\n    `\n  })\n\n  html += `</div>` // model-config-list\n\n  if (isRoot) {\n    html += `\n      <div style=\"display:flex;align-items:center;gap:10px;padding:14px 16px;border-top:1px solid var(--border)\">\n        <div id=\"mc-status\" style=\"flex:1;font-size:12px\"></div>\n        <button class=\"btn btn-sm\" onclick=\"loadModelConfig()\" style=\"font-size:12px\">↩ Đặt lại</button>\n        <button class=\"btn btn-primary btn-sm\" onclick=\"saveModelConfig()\" style=\"font-size:12px;font-weight:700\">💾 Lưu cấu hình</button>\n      </div>\n    `\n  }\n\n  html += `</div></div>` // section-body + section\n\n  // CSS for toggle switch (inline)\n  html += `\n    <style>\n      .toggle-label { position:relative; display:inline-block; width:36px; height:20px; }\n      .toggle-label input { opacity:0; width:0; height:0; }\n      .toggle-slider { position:absolute; inset:0; background:var(--border); border-radius:20px; transition:.25s; }\n      .toggle-slider:before { content:''; position:absolute; width:14px; height:14px; left:3px; bottom:3px; background:#fff; border-radius:50%; transition:.25s; }\n      .toggle-label input:checked + .toggle-slider { background:var(--success,#10b981); }\n      .toggle-label input:checked + .toggle-slider:before { transform:translateX(16px); }\n      .model-cfg-row.drag-over { border-color:var(--primary)!important; background:rgba(99,102,241,0.08)!important; }\n      .model-cfg-row.dragging  { opacity:0.4!important; }\n    </style>\n  `\n\n  el.innerHTML = html\n}\n\n// ─── Drag-and-drop logic ────────────────────────────────────────────────────────\nlet _mcDragSrcId = null\n\nfunction mcDragStart(e) {\n  const row = e.currentTarget\n  _mcDragSrcId = parseInt(row.dataset.id)\n  row.classList.add('dragging')\n  e.dataTransfer.effectAllowed = 'move'\n}\nfunction mcDragOver(e) {\n  e.preventDefault()\n  e.dataTransfer.dropEffect = 'move'\n  document.querySelectorAll('.model-cfg-row').forEach(r => r.classList.remove('drag-over'))\n  e.currentTarget.classList.add('drag-over')\n}\nfunction mcDrop(e) {\n  e.preventDefault()\n  const targetId = parseInt(e.currentTarget.dataset.id)\n  if (_mcDragSrcId === null || _mcDragSrcId === targetId) return\n\n  // Reorder _modelConfigRows by swapping positions\n  const srcIdx = _modelConfigRows.findIndex(m => m.id === _mcDragSrcId)\n  const tgtIdx = _modelConfigRows.findIndex(m => m.id === targetId)\n  if (srcIdx < 0 || tgtIdx < 0) return\n\n  const sorted = [..._modelConfigRows].sort((a,b) => a.sort_order - b.sort_order)\n  const srcItem = sorted.splice(sorted.findIndex(m => m.id === _mcDragSrcId), 1)[0]\n  const newTgtIdx = sorted.findIndex(m => m.id === targetId)\n  sorted.splice(newTgtIdx, 0, srcItem)\n\n  // Re-assign sort_order sequentially\n  sorted.forEach((m, i) => { m.sort_order = i + 1 })\n  _modelConfigRows = sorted\n  renderModelConfigEditor()\n}\nfunction mcDragEnd(e) {\n  document.querySelectorAll('.model-cfg-row').forEach(r => r.classList.remove('dragging','drag-over'))\n  _mcDragSrcId = null\n}\n\n// ─── Sync sort_order from number inputs ────────────────────────────────────────\nfunction mcSyncFromInputs() {\n  document.querySelectorAll('.mc-order').forEach(inp => {\n    const id = parseInt(inp.dataset.id)\n    const row = _modelConfigRows.find(m => m.id === id)\n    if (row) row.sort_order = parseInt(inp.value) || row.sort_order\n  })\n  // Re-sort and re-render to update badges\n  _modelConfigRows.sort((a,b) => a.sort_order - b.sort_order)\n  // Re-assign clean sequential orders\n  _modelConfigRows.forEach((m, i) => { m.sort_order = i + 1 })\n  renderModelConfigEditor()\n}\n\nfunction mcToggleEnabled(chk) {\n  const id = parseInt(chk.dataset.id)\n  const row = _modelConfigRows.find(m => m.id === id)\n  if (row) row.enabled = chk.checked ? 1 : 0\n  // Update row opacity live\n  const rowEl = chk.closest('.model-cfg-row')\n  if (rowEl) rowEl.style.opacity = chk.checked ? '1' : '0.5'\n}\n\n// ─── Save ──────────────────────────────────────────────────────────────────────\nasync function saveModelConfig() {\n  const statusEl = document.getElementById('mc-status')\n\n  // Collect latest values from inputs\n  const payload = _modelConfigRows.map(m => {\n    const timeoutInput = document.querySelector(`.mc-timeout[data-id=\"${m.id}\"]`)\n    const notesInput   = document.querySelector(`.mc-notes[data-id=\"${m.id}\"]`)\n    const enabledInput = document.querySelector(`.mc-enabled[data-id=\"${m.id}\"]`)\n    const orderInput   = document.querySelector(`.mc-order[data-id=\"${m.id}\"]`)\n    return {\n      id:         m.id,\n      sort_order: orderInput   ? parseInt(orderInput.value)   : m.sort_order,\n      enabled:    enabledInput ? (enabledInput.checked ? 1 : 0) : m.enabled,\n      timeout_ms: timeoutInput ? parseInt(timeoutInput.value) * 1000 : m.timeout_ms,\n      notes:      notesInput   ? notesInput.value : (m.notes || ''),\n    }\n  })\n\n  // Re-assign sequential sort_order from current row order\n  payload.sort((a,b) => a.sort_order - b.sort_order)\n  payload.forEach((p, i) => { p.sort_order = i + 1 })\n\n  if (statusEl) statusEl.innerHTML = '<span class=\"spinner\"></span> Đang lưu...'\n  try {\n    const d = await api('/model-config', { method:'PUT', body: JSON.stringify({ models: payload }) })\n    if (!d.success) throw new Error(d.message || 'Lỗi lưu cấu hình')\n    _modelConfigRows = d.models || _modelConfigRows\n    if (statusEl) statusEl.innerHTML = `<span style=\"color:var(--success)\">✅ Đã lưu lúc ${new Date().toLocaleTimeString('vi-VN')}</span>`\n    renderModelConfigEditor()\n  } catch(e) {\n    if (statusEl) statusEl.innerHTML = `<span style=\"color:var(--danger)\">❌ ${e.message}</span>`\n  }\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// PAGINATION HELPER\n// ═══════════════════════════════════════════════════════════════════════════════\nfunction renderPagination(containerId, page, totalPages, cb) {\n  const el = document.getElementById(containerId)\n  if (!el) return\n  if (totalPages <= 1) { el.innerHTML=''; return }\n  el.innerHTML = `\n    <button class=\"pg-btn\" ${page<=1?'disabled':''} onclick=\"(${cb.toString()})(${page-1})\">‹ Trước</button>\n    <span class=\"pg-info\">Trang ${page} / ${totalPages}</span>\n    <button class=\"pg-btn\" ${page>=totalPages?'disabled':''} onclick=\"(${cb.toString()})(${page+1})\">Sau ›</button>\n  `\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// INIT\n// ═══════════════════════════════════════════════════════════════════════════════\n;(async function init() {\n  if (TOKEN && ADMIN && ['rootadmin','subadmin'].includes(ADMIN.role)) {\n    try {\n      await api('/me')  // verify token still valid\n      initApp()\n    } catch {\n      doLogout()\n    }\n  }\n})()\n</script>\n</body>\n</html>\n"
